mapper.select:

FROM orders o
LEFT JOIN shops s ON s.id = o.shop_id
WHERE o.user_id = #{userId}

    AND (o.created_at < #{beforeCreatedAt}
         OR (o.created_at = #{beforeCreatedAt} AND o.id < #{beforeId}))

ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit}


FROM orders o
JOIN shops s ON s.id = o.shop_id
WHERE o.shop_id = #{shopId}

    AND (o.created_at < #{beforeCreatedAt}
         OR (o.created_at = #{beforeCreatedAt} AND o.id < #{beforeId}))

ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit}

SELECT id FROM orders WHERE status = 'UNPAID'
  AND pay_expires_at IS NOT NULL AND pay_expires_at <= #{now}
  AND (expiry_claim_until IS NULL OR expiry_claim_until <= NOW(3))
ORDER BY pay_expires_at, id LIMIT #{limit}
